[
    {
        "title": "读题找“多出”",
        "description": "设宿舍有 $x$ 间。若每间住 6 人，则总人数写成 $6x+34$。",
        "bubbleText": "题里最关键的是“多出34人”，先把它记成多出来的那一段。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 198.0,
            "y": 190.0
        }
    },
    {
        "title": "再看另一种住法",
        "description": "若每间住 7 人，却多出 4 间宿舍，说明实际可住的间数是 $x-4$，总人数可写成 $7(x-4)$。",
        "bubbleText": "“多出4间”不是人数变了，是可住的宿舍数少了 4 间。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 640.0,
            "y": 194.0
        }
    },
    {
        "title": "建立等量关系",
        "description": "同一所学校的寄宿学生总数不变，所以 $6x+34=7(x-4)$。",
        "bubbleText": "同一批学生，不管怎么住，总人数都一样，所以两边要相等。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 410.0,
            "y": 300.0
        }
    },
    {
        "title": "化简方程",
        "description": "展开得 $6x+34=7x-28$，移项得 $34+28=7x-6x$。",
        "bubbleText": "把带 $x$ 的放一边，数字放另一边，就更容易算了。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 336.0,
            "y": 513.0
        }
    },
    {
        "title": "求出宿舍间数",
        "description": "计算得 $62=x$，所以宿舍有 $62$ 间。",
        "bubbleText": "两边一减，$x$ 就只剩一个了，答案就出来了。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 652.0,
            "y": 516.0
        }
    },
    {
        "title": "求出寄宿人数",
        "description": "把 $x=62$ 代回 $6x+34$，得 $6\\times62+34=406$，所以寄宿学生有 $406$ 人。",
        "bubbleText": "先知道了宿舍间数，再代回去就能把总人数算出来。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 400.0,
            "y": 270.0
        }
    },
    {
        "title": "验算答案",
        "description": "验算：$406\\div6=67$ 余 $4$，正好表示“每间住6人还多34人”；同时 $406\\div7=58$ 余 $0$，可住 $58$ 间，少了 $4$ 间，也吻合题意。",
        "bubbleText": "最后检查一遍，两种说法都对上了，答案才算稳。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 400.0,
            "y": 270.0
        }
    }
]
